package tn.gov.onpf.controller;
import org.springframework.data.domain.Page; import org.springframework.web.bind.annotation.*; import tn.gov.onpf.service.FileWorkflowService; import java.util.*;
@RestController @RequestMapping("/operations") @CrossOrigin(origins="http://localhost:4200") public class OperationController { private final FileWorkflowService service; public OperationController(FileWorkflowService service){this.service=service;} @GetMapping public Page<Map<String,Object>> list(@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return service.operations(null,page,size);}@GetMapping("/file/{fileId}") public Page<Map<String,Object>> byFile(@PathVariable Long fileId,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return service.operations(fileId,page,size);} }
